"use client";

import { useEffect, useState } from "react";
import { withBase } from "@/lib/base-path";
import { useApp } from "./AppProvider";

/**
 * Registers public/sw.js (generated by scripts/gen-sw.ts at build time) and
 * shows a banner when a new version is waiting. Disabled in `next dev`.
 */
export function ServiceWorker() {
  const { t } = useApp();
  const [waiting, setWaiting] = useState<ServiceWorker | null>(null);

  useEffect(() => {
    if (process.env.NODE_ENV !== "production" || !("serviceWorker" in navigator)) return;

    let reloading = false;
    navigator.serviceWorker.addEventListener("controllerchange", () => {
      if (reloading) return;
      reloading = true;
      window.location.reload();
    });

    navigator.serviceWorker
      .register(withBase("/sw.js"), { scope: withBase("/") })
      .then((reg) => {
        if (reg.waiting && navigator.serviceWorker.controller) setWaiting(reg.waiting);
        reg.addEventListener("updatefound", () => {
          const sw = reg.installing;
          sw?.addEventListener("statechange", () => {
            // A new SW installed while an old one controls the page → update ready.
            if (sw.state === "installed" && navigator.serviceWorker.controller) setWaiting(sw);
          });
        });
      })
      .catch((err) => console.warn("SW registration failed", err));
  }, []);

  if (!waiting) return null;
  return (
    <div
      role="status"
      className="fixed inset-x-3 top-3 z-50 mx-auto flex max-w-md items-center justify-between gap-3 rounded-xl border border-border bg-surface p-3 shadow-lg"
    >
      <span className="text-sm">{t("update.available")}</span>
      <button
        type="button"
        onClick={() => waiting.postMessage({ type: "SKIP_WAITING" })}
        className="min-h-11 rounded-lg bg-accent px-4 font-semibold text-accent-contrast"
      >
        {t("update.reload")}
      </button>
    </div>
  );
}
